namespace SB.GestionSolicitudes.Dominio.Notificaciones;

/// <summary>
/// Notification generated by a relevant business event (creation, assignment,
/// state change, closing). It is persisted so it can be audited and replayed.
/// </summary>
public class Notificacion
{
    public const int LONGITUD_MAXIMA_ASUNTO = 200;
    public const int LONGITUD_MAXIMA_MENSAJE = 1000;

    public int Id { get; set; }

    public int SolicitudId { get; set; }

    public Solicitudes.Solicitud? Solicitud { get; set; }

    public int DestinatarioId { get; set; }

    public Usuarios.Usuario? Destinatario { get; set; }

    public CanalNotificacion Canal { get; set; }

    public string Asunto { get; set; } = string.Empty;

    public string Mensaje { get; set; } = string.Empty;

    public EstadoNotificacion Estado { get; set; } = EstadoNotificacion.Pendiente;

    public DateTime Fecha { get; set; }

    public bool Leida { get; set; }
}
